(() => { const temiz = v => Array.isArray(v) ? v.filter(x => !(x && x.ornek === true)).map(temiz) : (v && typeof v === 'object' ? (Object.keys(v).forEach(k => { v[k] = temiz(v[k]); }), v) : v); GMV.rotalar = temiz(GMV.rotalar); })();
